pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        // Keep the domain wide: any caller who is not the deployer (the owner),
        // and any positive funding amount.
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1e30);

        // Fund the contract through its public payable surface.
        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "funding failed");
        require(address(c).balance == amount, "funding mismatch");

        // An arbitrary (non-owner) caller attempts to withdraw everything.
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // Rule: a non-owner's withdrawAll never succeeds AND the contract's
        // funds remain intact afterwards. The mutant lets the non-owner
        // succeed and drain the balance, breaking this rule.
        assertTrue(!ok && address(c).balance == amount);
    }
}

