pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, type(uint256).max / 2);

        // fund the contract through its payable fallback (depositsCount increments)
        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent);

        // an arbitrary fuzzed caller attempts to withdraw the whole balance
        bool ok;
        vm.prank(actor);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // RULE: withdrawAll may only succeed for the owner; a non-owner's call
        // must revert. The mutant lets any non-owner successfully drain c.
        assertTrue(!ok || actor == c.owner(), "non-owner withdrew all funds");
    }
}

