pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint240).max);
        // fund c with the fuzzed amount so the withdrawal is admissible
        vm.deal(address(c), amount);

        address owner = c.owner();
        vm.prank(owner);
        c.withdraw(amount); // drains the whole balance in the reference

        // rule: with zero balance left, any further withdrawal must revert
        vm.prank(owner);
        bool ok;
        try c.withdraw(1) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "withdrawal from an empty contract must revert");
    }
}

