    function test(uint amt) public {
        require(amt > 0);
        // c.sendMoney(address(this), amt): address(this) has no receive/fallback,
        // so the low-level call inside sendMoney fails.
        // P: require(__sent_result100) makes sendMoney revert => probe returns false.
        // M: failed call is ignored => sendMoney succeeds => probe returns true.
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature("sendMoney(address,uint256)", address(this), amt)
        );
        assert(!ok);
    }
}

